/**
 * Database schema (Drizzle, SQLite). Conventions:
 * - Primary keys: text UUIDv7 (`id`), generated by the app (or = client opId for commands).
 * - Timestamps: integer epoch milliseconds UTC, suffix `At`.
 * - Local calendar values (dates in the class timezone): text 'YYYY-MM-DD'.
 * - Translatable, teacher-editable labels: JSON `{ en?: string, tr?: string }` (type LocalizedText).
 * - Never hard-delete history: use `archivedAt` / `voidedAt` / `deactivatedAt`.
 * Each stage appends its tables to the relevant section; generate migrations with `npm run db:generate`.
 */
import { sql } from 'drizzle-orm';
import { integer, sqliteTable, text, uniqueIndex, index } from 'drizzle-orm/sqlite-core';

export type LocalizedText = { en?: string; tr?: string };

// ---------------------------------------------------------------- school & settings
export const schoolSettings = sqliteTable('school_settings', {
  id: integer('id').primaryKey(), // always 1
  schoolName: text('school_name').notNull().default('Class Compass School'),
  timezone: text('timezone').notNull().default('Europe/Istanbul'),
  weekStartsOn: integer('week_starts_on').notNull().default(1), // 1 = Monday
  defaultLocale: text('default_locale', { enum: ['en', 'tr'] }).notNull().default('en'),
  updatedAt: integer('updated_at').notNull(),
});

// ---------------------------------------------------------------- accounts
export const users = sqliteTable(
  'users',
  {
    id: text('id').primaryKey(),
    login: text('login').notNull(), // stored lower-cased (tr-insensitive fold applied by service)
    email: text('email'),
    displayName: text('display_name').notNull(),
    role: text('role', { enum: ['admin', 'teacher'] }).notNull(),
    passwordHash: text('password_hash').notNull(),
    pinHash: text('pin_hash'),
    locale: text('locale', { enum: ['en', 'tr'] }).notNull().default('en'),
    textScale: integer('text_scale').notNull().default(100),
    mustChangePassword: integer('must_change_password', { mode: 'boolean' }).notNull().default(false),
    disabledAt: integer('disabled_at'),
    createdAt: integer('created_at').notNull(),
    updatedAt: integer('updated_at').notNull(),
  },
  (t) => [uniqueIndex('users_login_uq').on(t.login)],
);

export const sessions = sqliteTable(
  'sessions',
  {
    id: text('id').primaryKey(),
    tokenHash: text('token_hash').notNull(),
    kind: text('kind', { enum: ['user', 'student'] }).notNull(),
    userId: text('user_id').references(() => users.id),
    studentLinkId: text('student_link_id'),
    classroomMode: integer('classroom_mode', { mode: 'boolean' }).notNull().default(false),
    pinUnlockedUntil: integer('pin_unlocked_until'),
    pinFailures: integer('pin_failures').notNull().default(0),
    pinLockedUntil: integer('pin_locked_until'),
    createdAt: integer('created_at').notNull(),
    lastSeenAt: integer('last_seen_at').notNull(),
    expiresAt: integer('expires_at').notNull(),
    revokedAt: integer('revoked_at'),
  },
  (t) => [uniqueIndex('sessions_token_uq').on(t.tokenHash), index('sessions_user_idx').on(t.userId)],
);

/** Login throttling per account and per IP. */
export const authAttempts = sqliteTable(
  'auth_attempts',
  {
    key: text('key').primaryKey(), // e.g. 'login:user:<id>' | 'login:ip:<ip>'
    failures: integer('failures').notNull().default(0),
    lockedUntil: integer('locked_until'),
    updatedAt: integer('updated_at').notNull(),
  },
);

export const oneTimeTokens = sqliteTable('one_time_tokens', {
  id: text('id').primaryKey(),
  kind: text('kind', { enum: ['password_reset'] }).notNull(),
  userId: text('user_id').notNull().references(() => users.id),
  tokenHash: text('token_hash').notNull(),
  expiresAt: integer('expires_at').notNull(),
  usedAt: integer('used_at'),
  createdAt: integer('created_at').notNull(),
});

// ---------------------------------------------------------------- idempotency & audit
/** Every client command (opId) is recorded with its result in the same transaction as its effect. */
export const commandLog = sqliteTable('command_log', {
  opId: text('op_id').primaryKey(),
  actorKey: text('actor_key').notNull(), // 'user:<id>' | 'student:<id>'
  type: text('type').notNull(),
  requestHash: text('request_hash').notNull(),
  resultJson: text('result_json').notNull(),
  createdAt: integer('created_at').notNull(),
});

/** Insert-only audit trail for important edits (DAT-5, ACC-9). */
export const auditEvents = sqliteTable(
  'audit_events',
  {
    id: text('id').primaryKey(),
    at: integer('at').notNull(),
    actorType: text('actor_type', { enum: ['user', 'student', 'system'] }).notNull(),
    actorId: text('actor_id'),
    opId: text('op_id'),
    action: text('action').notNull(),
    entity: text('entity').notNull(),
    entityId: text('entity_id'),
    beforeJson: text('before_json'),
    afterJson: text('after_json'),
  },
  (t) => [index('audit_entity_idx').on(t.entity, t.entityId), index('audit_at_idx').on(t.at)],
);

export const _sqlHelper = sql; // re-export for raw fragments in repos
